<div class="admin-nav"><div class="container"><strong>Admin</strong> <a href="<?=base_url('admin')?>">Dashboard</a><a href="<?=base_url('admin/products')?>">Products</a><a href="<?=base_url('admin/orders')?>">Orders</a></div></div><div class="dashboard-wrap"><h1>Orders</h1><table class="orders-table"><tr><th>ID</th><th>Customer</th><th>Email</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o): ?><tr><td>#<?=$o->id?></td><td><?=html_escape($o->username)?></td><td><?=html_escape($o->email)?></td><td><?=money($o->total)?></td><td><?=html_escape($o->payment_method)?></td><td><?=html_escape($o->status)?></td><td><?=form_open('admin/orders/status/'.$o->id)?><select name="status"><?php foreach(array('Processing','Confirmed','Shipped','Delivered','Cancelled') as $s): ?><option <?=$s===$o->status?'selected':''?>><?=$s?></option><?php endforeach; ?></select><button>Save</button></form></td></tr><?php endforeach; ?></table></div>
